fn extract_rear_chars(s: &Vec<Vec<char>>) -> Vec<char> {
    // Pre-allocate the result with the same length as `s`
    let mut result = Vec::with_capacity(s.len());

    // For each inner Vec<char>, take its last character
    for inner in s {
        // We can safely unwrap because each inner Vec is guaranteed non-empty
        let last_char = *inner.last().unwrap();
        result.push(last_char);
    }

    result
}

fn main() {
    // Example usages and simple tests
    let input1: Vec<Vec<char>> = vec![
        vec!['a', 'b', 'c'],
        vec!['x', 'y'],
        vec!['z'],
    ];
    assert_eq!(extract_rear_chars(&input1), vec!['c', 'y', 'z']);

    let input2: Vec<Vec<char>> = vec![
        vec!['h', 'e', 'l', 'l', 'o'],
        vec!['w', 'o', 'r', 'l', 'd'],
    ];
    assert_eq!(extract_rear_chars(&input2), vec!['o', 'd']);

    let empty_outer: Vec<Vec<char>> = Vec::new();
    assert_eq!(extract_rear_chars(&empty_outer), Vec::new());

    println!("All tests passed!");
}